package dualshock4

import (
	"bytes"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func reportBytes(t *testing.T) []byte {
	t.Helper()
	for _, iface := range defaultDescriptor.Interfaces {
		if iface.HID != nil {
			rb, err := iface.HID.ReportBytes()
			require.NoError(t, err)
			return []byte(rb)
		}
	}
	t.Fatal("no HID interface in descriptor")
	return nil
}

// The HID report descriptor must match the real DS4 v2 (CUH-ZCT2,
// PID 054C:09CC): 507 bytes (DS4Dongle desc_hid_report_ds4).
func TestReportDescriptorLength(t *testing.T) {
	assert.Len(t, reportBytes(t), 507)
}

