// HID interrupt endpoints use the stock DS4 v2 polling interval.
func TestHIDEndpointsInterval5(t *testing.T) {
	for _, iface := range defaultDescriptor.Interfaces {
		if iface.HID == nil {
			continue
		}
		require.Len(t, iface.Endpoints, 2)
		for _, ep := range iface.Endpoints {
			assert.Equal(t, uint8(5), ep.BInterval)
		}
	}
}
